다음 C 언어로 구현된 프로그램을 분석하여 그 실행 결과를 쓰시오. (단, 출력문의 출력
서식을 준수하시오.) (5점)
#include <stdio.h>
#define SIZE 3
typedef struct {
int a[SIZE];
int front;
int rear;
} Queue;
void enq(Queue* q, int val) {
q -> a[q -> rear] = val;
q -> rear = (q -> rear + 1) % SIZE;
}
int deq(Queue* q) {
int val = q -> a[q -> front];
q -> front = (q -> front + 1) % SIZE;
return val;
}
int main( ) {
Queue q = {{0}, 0, 0};
enq(&q, 1);
enq(&q, 2);
deq(&q);
enq(&q, 3);
printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}

questions.explanation:
#include <stdio.h>
#define SIZE 3 // 3을 SIZE로 정의한다. 프로그램 안에서 SIZE는 숫자 3과 동일하다.
typedef struct { // 구조체를 정의한다.
int a[SIZE]; // 크기가 3인 정수형 배열 a를 선언한다.
int front; // 정수형 변수 front를 선언한다.
int rear; // 정수형 변수 rear을 선언한다.
struct Queue
int a[3] (12Byte) int front (4Byte) int rear (4Byte)
} Queue; // 구조체의 이름은 Queue이다.
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
enq(&q, 2);
deq(&q);
enq(&q, 3);
printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
모든 C 언어 프로그램은 반드시 main( ) 함수에서 시작한다.
❶ Queue 자료형 변수 q를 선언하고, Queue의 배열 a, front, rear을 각각 0으로 초기화한다. q가 가리키고
있는 1004 번지는 Queue 구조체의 크기만큼 할당된 공간이므로 q는 1004번지 이후의 20Byte를 의미한다.
(이후 그림에서 지정한 주소는 임의로 정한 것이며, 이해를 돕기 위해 10진수로 표현했다.)
메모리
주소
0000 q 1004
ㆍㆍㆍ
20Byte
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
0 0 0 0 0
ㆍㆍㆍ
9999
❷ q의 주소와 1을 인수로 enq( ) 함수를 호출한다.
❸ void enq(Queue* q, int val) {
❹ q -> a[q -> rear] = val;
❺ q -> rear = (q -> rear + 1) % SIZE;
}
❸ 반환값이 없는 enq( ) 함수의 시작점이다. ❷번에서 전달한 배열 a의 주소를 q가, 1을 val이 받는다.
❹ q가 가리키는 rear은 0이므로 q가 가리키는 a[0]에 val의 값 1을 저장한다.
❺ q가 가리키는 rear에 ‘(q -> rear + 1) % SIZE’, 즉 (0 + 1) % 3이므로 1을 저장한 후 제어를 enq( ) 함수
를 호출했던 ❷번의 다음 줄인 ❻번으로 옮긴다.
메모리
주소
0000 q 1004
ㆍㆍㆍ
20Byte
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 0 0 0 1
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
deq(&q);
enq(&q, 3);
printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
❻ q의 주소와 2를 인수로 enq( ) 함수를 호출한다.
❼ void enq(Queue* q, int val) {
❽ q -> a[q -> rear] = val;
❾ q -> rear = (q -> rear + 1) % SIZE;
}
❼ 반환값이 없는 enq( ) 함수의 시작점이다. ❻번에서 전달한 배열 a의 주소를 q가, 2를 val이 받는다.
❽ q가 가리키는 rear은 1이므로 q가 가리키는 a[1]에 val의 값 2를 저장한다.
❾ q가 가리키는 rear에 ‘(q -> rear + 1) % SIZE’, 즉 (1 + 1) % 3이므로 2를 저장한 후 제어를 enq( ) 함수
를 호출했던 ❻번의 다음 줄인 ❿번으로 옮긴다.
메모리
주소
0000 q 1004
ㆍㆍㆍ
20Byte
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 2 0 0 2
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
❿ deq(&q);
enq(&q, 3);
printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
❿ q의 주소를 인수로 deq( ) 함수를 호출한다.
⓫ int deq(Queue* q) {
⓬ int val = q -> a[q -> front];
⓭ q -> front = (q -> front + 1) % SIZE;
⓮ return val;
}
⓫ 정수를 반환하는 deq( ) 함수의 시작점이다. ❿번에서 전달한 배열 a의 주소를 q가 받는다.
⓬ 정수형 변수 val을 선언하고, q가 가리키는 front가 0이므로 q가 가리키는 a[0]의 값 1로 초기화한다.
⓭ q가 가리키는 front에 ‘(q -> front + 1) % SIZE’, 즉 (0 + 1) % 3이므로 1을 저장한다.
⓮ deq( ) 함수를 호출했던 곳으로 val을 반환하면서 제어를 ❿번의 다음 줄인 ⓯번으로 옮긴다.
메모리
주소
0000 q 1004
ㆍㆍㆍ
20Byte
val 1
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 2 0 1 2
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
❿ deq(&q);
⓯ enq(&q, 3);
printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
⓯ q의 주소와 3을 인수로 enq( ) 함수를 호출한다.
⓰ void enq(Queue* q, int val) {
⓱ q -> a[q -> rear] = val;
⓲ q -> rear = (q -> rear + 1) % SIZE;
}
⓰ 반환값이 없는 enq( ) 함수의 시작점이다. ⓯번에서 전달한 배열 a의 주소를 q가, 3을 val이 받는다.
⓱ q가 가리키는 rear은 2이므로 q가 가리키는 a[2]에 val의 값 3을 저장한다.
⓲ q가 가리키는 rear에 ‘(q -> rear + 1) % SIZE’, 즉 (2 + 1) % 3이므로 0을 저장한 후 제어를 enq( ) 함수
를 호출했던 ⓯번의 다음 줄인 ⓳번으로 옮긴다.
메모리
주소
q 1004
0000
ㆍㆍㆍ
20Byte
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 2 3 1 0
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
❿ deq(&q);
⓯ enq(&q, 3);
⓳ printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
⓳ q의 주소를 인수로 deq( ) 함수를 두 번 호출한 후 반환받은 값을 “%d 그리고 %d” 출력 서식에 적용하여
출력한다. 먼저 q의 주소를 인수로 deq( ) 함수를 호출한다.
⓴ int deq(Queue* q) {
㉑ int val = q -> a[q -> front];
㉒ q -> front = (q -> front + 1) % SIZE;
㉓ return val;
}
⓴ 정수를 반환하는 deq( ) 함수의 시작점이다. ⓳번에서 전달한 배열 a의 주소를 q가 받는다.
㉑ 정수형 변수 val을 선언하고, q가 가리키는 front가 1이므로 q가 가리키는 a[1]의 값 2로 초기화한다.
㉒ q가 가리키는 front에 ‘(q -> front + 1) % SIZE’, 즉 (1 + 1) % 3이므로 2를 저장한다.
㉓ deq( ) 함수를 호출했던 ㉔번으로 val의 값 2를 반환한다.
메모리
주소
q 1004
0000
ㆍㆍㆍ
20Byte
val 2
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 2 3 2 0
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
❿ deq(&q);
⓯ enq(&q, 3);
⓳㉔ printf("%d 그리고 %d", deq(&q), deq(&q));
return 0;
}
㉔ 이어서 q의 주소를 인수로 deq( ) 함수를 다시 한 번 호출한다.
㉕ int deq(Queue* q) {
㉖ int val = q -> a[q -> front];
㉗ q -> front = (q -> front + 1) % SIZE;
㉘ return val;
}
㉕ 정수를 반환하는 deq( ) 함수의 시작점이다. ㉔번에서 전달한 배열 a의 주소를 q가 받는다.
㉖ 정수형 변수 val을 선언하고, q가 가리키는 front가 2이므로 q가 가리키는 a[2]의 값 3으로 초기화한다.
㉗ q가 가리키는 front에 ‘(q -> front + 1) % SIZE’, 즉 (2 + 1) % 3이므로 0을 저장한다.
㉘ deq( ) 함수를 호출했던 ㉙번으로 val의 값 3을 반환한다.
메모리
주소
q 1004
0000
ㆍㆍㆍ
20Byte
val 3
1000 1004 1008 1012 1016 1020 1024 1028 ㆍㆍㆍ
배열 a
1000 front rear
a[0] a[1] a[2]
1 2 3 0 0
ㆍㆍㆍ
9999
int main( ) {
❶ Queue q = {{0}, 0, 0};
❷ enq(&q, 1);
❻ enq(&q, 2);
❿ deq(&q);
⓯ enq(&q, 3);
⓳㉔㉙ printf("%d 그리고 %d", deq(&q), deq(&q));
㉚ return 0;
}
㉙ ㉓번으로부터 반환받은 2와 공백 한 칸을 출력하고 그리고를 출력한 후 공백 한 칸과 ㉘번으로부터 반환받은
3을 출력한다.
결과 2 그리고 3
㉚ main( ) 함수에서의 ‘return 0’은 프로그램의 종료를 의미한다.

